// DKT-4252: the rendered packet elides generated-file hunks, so a review of a
// regenerated change stays under the Workflow script cap.

const packetCap = 524288

// generatedSection renders a unified-diff section for a generated file of
// roughly size bytes.
func generatedSection(path string, size int) string {
	var b strings.Builder
	fmt.Fprintf(&b, "diff --git a/%s b/%s\nindex 1111111..2222222 100644\n--- a/%s\n+++ b/%s\n@@ -1,3 +1,3 @@\n", path, path, path, path)
	b.WriteString("-// Code generated by protoc-gen-go. DO NOT EDIT.\n+// Code generated by protoc-gen-go. DO NOT EDIT.\n")
	for b.Len() < size {
		b.WriteString("+var _ = \"generated filler line that is long enough to add up quickly\"\n")
	}
	return b.String()
}

const handWritten = "diff --git a/internal/hand.go b/internal/hand.go\nindex aaaaaaa..bbbbbbb 100644\n" +
	"--- a/internal/hand.go\n+++ b/internal/hand.go\n@@ -1 +1 @@\n-old line\n+new line\n"

func TestElideGeneratedDiffKeepsHandWrittenHunks(t *testing.T) {
	diff := generatedSection("api/x.pb.go", 800*1024) + handWritten
	out, elided := elideGeneratedDiff(diff, nil, nil)

	if len(out) >= packetCap {
		t.Errorf("elided diff is %d bytes; want under the %d cap", len(out), packetCap)
	}
	if !strings.Contains(out, handWritten) {
		t.Errorf("the hand-written hunks were not kept verbatim:\n%s", out)
	}
	if len(elided) != 1 || elided[0].Path != "api/x.pb.go" || elided[0].Blob != "2222222" ||
		elided[0].Adds < 1000 || elided[0].Dels != 1 {
		t.Errorf("elided = %+v; want api/x.pb.go with blob 2222222 and its line counts", elided)
	}
	for _, want := range []string{"# generated file, hunks elided from this packet: api/x.pb.go", "blob 2222222"} {
		if !strings.Contains(out, want) {
			t.Errorf("stat line lacks %q:\n%s", want, out)
		}
	}
	if strings.Contains(out, "filler line") {
		t.Error("the generated hunks were carried verbatim")
	}
}

func TestElideGeneratedDiffLeavesAnOrdinaryDiffByteIdentical(t *testing.T) {
	if out, elided := elideGeneratedDiff(handWritten, nil, nil); out != handWritten || len(elided) != 0 {
		t.Errorf("an ordinary diff changed: %q, %+v", out, elided)
	}
	if out, elided := elideGeneratedDiff("not a diff at all\n", nil, nil); out != "not a diff at all\n" || len(elided) != 0 {
		t.Errorf("a non-diff body changed: %q, %+v", out, elided)
	}
}

func TestElideGeneratedDiffHonoursLinguistGenerated(t *testing.T) {
	attrs := parseGeneratedAttributes("# generated\n*.lock linguist-generated\ndocs/api/** -linguist-generated\n")
	section := "diff --git a/deps/x.lock b/deps/x.lock\nindex 3333333..4444444 100644\n--- a/deps/x.lock\n+++ b/deps/x.lock\n@@ -1 +1 @@\n-a\n+b\n"

	out, elided := elideGeneratedDiff(section+handWritten, attrs, nil)
	if len(elided) != 1 || elided[0].Path != "deps/x.lock" || !strings.Contains(out, handWritten) {
		t.Errorf("linguist-generated file not elided: %+v\n%s", elided, out)
	}
	if parseGeneratedAttributes("# nothing here\n") != nil {
		t.Error("attributes with no linguist-generated rule mark files generated")
	}
}

// `**` crosses directories, as in git; `*` in an anchored pattern does not.
func TestGitattributesPatternsMatchNestedPaths(t *testing.T) {
	attrs := parseGeneratedAttributes("vendor/** linguist-generated\n**/*.pb.go linguist-generated\n" +
		"gen/**/out.txt linguist-generated\n/top.txt linguist-generated\napi/*.json linguist-generated\n")
	for p, want := range map[string]bool{
		"vendor/a/b.go":    true,
		"vendor":           false,
		"proto/x/y.pb.go":  true,
		"y.pb.go":          true,
		"gen/out.txt":      true,
		"gen/a/b/out.txt":  true,
		"top.txt":          true,
		"sub/top.txt":      false,
		"api/x.json":       true,
		"api/v1/x.json":    false,
		"internal/hand.go": false,
		"notvendor/a/b.go": false,
	} {
		if got := attrs(p); got != want {
			t.Errorf("%s: generated = %v, want %v", p, got, want)
		}
	}
}

// The attributes are read from the commit the run pinned, so a later edit to
// the checkout's .gitattributes changes nothing a render elides.
func TestGitattributesAreReadFromThePinnedCommit(t *testing.T) {
	repo := t.TempDir()
	gitRun(t, repo, "init", "-q")
	writeFile(t, repo, ".gitattributes", "*.lock linguist-generated\n")
	gitRun(t, repo, "add", "-A")
	gitRun(t, repo, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "base")
	pinned := strings.TrimSpace(gitRun(t, repo, "rev-parse", "HEAD"))
	writeFile(t, repo, ".gitattributes", "*.go linguist-generated\n")

	attrs := gitattributesGenerated(repo, pinned)
	if attrs == nil || !attrs("deps/x.lock") || attrs("internal/hand.go") {
		t.Fatal("the attributes were not those of the pinned commit")
	}
	if gitattributesGenerated(repo, "") != nil {
		t.Error("a run with no pinned commit marks files generated")
	}
}

// TestRenderedPacketElidesGeneratedHunks is the acceptance check: a review
// step whose issue.diff carries an 800 KB generated file renders under the cap
// with the hand-written hunks intact and the generated file as a stat line —
// and the recorded artifact keeps the whole diff.
func TestRenderedPacketElidesGeneratedHunks(t *testing.T) {
	conn := mustDB(t)
	registerFixture(t, conn)
	issue := createIssue(t, conn, "regenerated", "body", "task", nil)
	run := startRun(t, conn, issue)
	_, err := activate(conn, run.ID)
	testsupport.Must(t, err, "activate: %v", err)

	diff := generatedSection("api/x.pb.go", 800*1024) + handWritten
	e := testEngine()
	e.HeadFn = nil // the worktree is a plain directory: no head to record or bind
	e.DiffFn = func(_, _ string, _ []string) (string, error) { return diff, nil }
	completeStepAt(t, conn, e, issue, "implement@0", t.TempDir())

	rendered, err := RenderStep(conn, stepIDIn(t, conn, issue, "review@0#0"), "", nowMS)
	testsupport.Must(t, err, "RenderStep: %v", err)
	if len(rendered.Packet) >= packetCap {
		t.Errorf("rendered packet is %d bytes; want under %d", len(rendered.Packet), packetCap)
	}
	if !strings.Contains(rendered.Packet, handWritten) ||
		!strings.Contains(rendered.Packet, "hunks elided from this packet: api/x.pb.go") {
		t.Errorf("packet lacks the intact hand-written hunks or the stat line")
	}

	ctx, err := ReadContext(conn, stepIDIn(t, conn, issue, "review@0#0"), nowMS)
	testsupport.Must(t, err, "ReadContext: %v", err)
	whole := false
	for _, in := range ctx.Inputs {
		if in.Kind == ArtifactKindIssueDiff && strings.Contains(in.Body, "filler line") {
			whole = true
		}
	}
	if !whole {
		t.Error("the recorded issue.diff no longer carries the generated hunks")
	}
}

// A writer must not be able to hide hand-written code from the reviewer by
// putting the generated marker into it.
func TestAForgedGeneratedMarkerDoesNotHideHandWrittenCode(t *testing.T) {
	forged := map[string]string{
		"added to an existing file": "diff --git a/internal/x.go b/internal/x.go\nindex a..b 100644\n--- a/internal/x.go\n+++ b/internal/x.go\n" +
			"@@ -1,2 +1,3 @@\n+// Code generated by hand. DO NOT EDIT.\n package x\n \n+func Backdoor() {}\n",
		"quoted in a later hunk": "diff --git a/internal/x.go b/internal/x.go\nindex a..b 100644\n--- a/internal/x.go\n+++ b/internal/x.go\n" +
			"@@ -50,2 +50,3 @@\n // Code generated by protoc. DO NOT EDIT.\n+func Backdoor() {}\n x\n",
		"mentioned mid-line": "diff --git a/internal/x.go b/internal/x.go\nindex a..b 100644\n--- a/internal/x.go\n+++ b/internal/x.go\n" +
			"@@ -1,2 +1,3 @@\n package x\n+var s = \"Code generated by x DO NOT EDIT\"\n+func Backdoor() {}\n",
		"hunk at line 10": "diff --git a/internal/x.go b/internal/x.go\nindex a..b 100644\n--- a/internal/x.go\n+++ b/internal/x.go\n" +
			"@@ -10,2 +10,3 @@\n // Code generated by protoc. DO NOT EDIT.\n+func Backdoor() {}\n x\n",
	}
	for name, diff := range forged {
		t.Run(name, func(t *testing.T) {
			out, elided := elideGeneratedDiff(diff, nil, nil)
			if len(elided) != 0 || out != diff {
				t.Fatalf("hand-written change was elided: %+v\n%s", elided, out)
			}
		})
	}
}

// A file the change creates has no earlier state, so a header among its added
// lines proves nothing: anyone can write the line.
func TestACreatedFileIsNotElidedByItsOwnHeader(t *testing.T) {
	diff := "diff --git a/internal/auth/bypass.go b/internal/auth/bypass.go\nnew file mode 100644\nindex 0000000..2222222\n" +
		"--- /dev/null\n+++ b/internal/auth/bypass.go\n" +
		"@@ -0,0 +1,3 @@\n+// Code generated by hand DO NOT EDIT.\n+package auth\n+func Bypass() {}\n"
	if out, elided := elideGeneratedDiff(diff, nil, func(string) bool { return true }); len(elided) != 0 || out != diff {
		t.Fatalf("a created file was elided by its own header: %+v", elided)
	}
	attrs := parseGeneratedAttributes("internal/auth/*.go linguist-generated\n")
	if _, elided := elideGeneratedDiff(diff, attrs, nil); len(elided) != 1 {
		t.Fatalf("a created file the pinned attributes mark generated was not elided: %+v", elided)
	}
}

// A generated file whose header the change removes is now hand-written, and
// the reviewer reads it in full.
func TestRemovingTheGeneratedHeaderKeepsTheFileInThePacket(t *testing.T) {
	diff := "diff --git a/api/x.pb.go b/api/x.pb.go\nindex 1111111..2222222 100644\n--- a/api/x.pb.go\n+++ b/api/x.pb.go\n" +
		"@@ -1,3 +1,3 @@\n-// Code generated by protoc-gen-go. DO NOT EDIT.\n+// hand-maintained now\n package api\n-var x = 1\n+func Backdoor() {}\n"
	header := func(blob string) bool { return blob == "1111111" }
	if out, elided := elideGeneratedDiff(diff, nil, header); len(elided) != 0 || out != diff {
		t.Fatalf("a file whose generated header was removed was elided: %+v", elided)
	}
}

// The stat counts content lines only: a removed `-- x` line renders as
// `--- x` and an added `++i` as `+++i`, and both are content.
func TestElidedStatCountsDashAndPlusContentLines(t *testing.T) {
	diff := "diff --git a/db/gen.sql b/db/gen.sql\nindex 1111111..2222222 100644\n--- a/db/gen.sql\n+++ b/db/gen.sql\n" +
		"@@ -1,3 +1,3 @@\n--- comment\n+++i\n context\n-x\n+y\n"
	_, elided := elideGeneratedDiff(diff, parseGeneratedAttributes("*.sql linguist-generated\n"), nil)
	if len(elided) != 1 || elided[0].Adds != 2 || elided[0].Dels != 2 {
		t.Fatalf("elided = %+v; want +2 -2", elided)
	}
}

// The out-of-scope disclosure heading rides at the end of the last in-scope
// section. If that file is generated it must survive the elision, or the hunks
// that follow read as in-scope.
func TestElisionKeepsTheOutOfScopeHeading(t *testing.T) {
	trailer := "# issue.diff: 1 changed file(s) fall outside this issue's declared scope and are excluded from the diff above:\n" +
		"#   internal/other.go\n" + outOfScopeMarker + " their hunks follow ===\n# read them as evidence.\n"
	diff := generatedSection("api/x.pb.go", 4096) + trailer + handWritten
	out, elided := elideGeneratedDiff(diff, nil, nil)
	if len(elided) != 1 {
		t.Fatalf("elided = %+v; want the generated file", elided)
	}
	for _, line := range strings.SplitAfter(trailer, "\n") {
		if line != "" && !strings.Contains(out, line) {
			t.Errorf("the elided diff lost the heading line %q", line)
		}
	}
}

// A REGENERATED file's real git diff starts its first hunk deep in the file, so
// the header never appears in it. The header is read from the file's old blob.
func TestARegeneratedFileIsElidedByItsOldBlobHeader(t *testing.T) {
	repo := t.TempDir()
	gitRun(t, repo, "init", "-q")
	var gen, hand strings.Builder
	gen.WriteString("// Code generated by protoc-gen-go. DO NOT EDIT.\n")
	hand.WriteString("package hand\n")
	for i := 0; i < 400; i++ {
		fmt.Fprintf(&gen, "var g%d = %d\n", i, i)
		fmt.Fprintf(&hand, "var h%d = %d\n", i, i)
	}
	// The hand-written file mentions the phrase deep inside, never as line 1.
	hand.WriteString("// Code generated by hand. DO NOT EDIT.\n")
	writeFile(t, repo, "api/x.pb.go", gen.String())
	writeFile(t, repo, "pkg/hand.go", hand.String())
	gitRun(t, repo, "add", "-A")
	gitRun(t, repo, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "base")

	writeFile(t, repo, "api/x.pb.go", strings.Replace(gen.String(), "var g200 = 200", "var g200 = 201", 1))
	writeFile(t, repo, "pkg/hand.go", strings.Replace(hand.String(), "var h200 = 200", "var h200 = 201", 1))
	gitRun(t, repo, "add", "-A") // the after blobs are in the object database, as a writer's commit puts them
	diff := gitRun(t, repo, "diff", "--cached", "--full-index")
	if strings.Contains(diff, "Code generated") {
		t.Fatal("premise: the header is in the diff, so the hunk is not deep")
	}

	blobs := newBlobHeaderReader(repo)
	defer blobs.Close()
	out, elided := elideGeneratedDiff(diff, nil, blobs.Has)
	if len(elided) != 1 || elided[0].Path != "api/x.pb.go" {
		t.Fatalf("elided = %+v, want only api/x.pb.go", elided)
	}
	if !strings.Contains(out, "var h200 = 201") {
		t.Error("the hand-written hunk was elided")
	}
	if strings.Contains(out, "var g200 = 201") {
		t.Error("the generated hunk stayed inline")
	}
	if _, kept := elideGeneratedDiff(diff, nil, nil); len(kept) != 0 {
		t.Error("without the blob reader the deep hunk was elided; the premise is wrong")
	}
}

// The same, through the render: a regenerated file whose diff starts deep in
// the file is abridged because the run's checkout holds its old blob.
func TestRenderedPacketElidesARegeneratedFileByItsOldBlob(t *testing.T) {
	repo := t.TempDir()
	gitRun(t, repo, "init", "-q")
	writeFile(t, repo, "api/x.pb.go", "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage api\n")
	gitRun(t, repo, "add", "-A")
	gitRun(t, repo, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "base")
	blob := strings.TrimSpace(gitRun(t, repo, "rev-parse", "HEAD:api/x.pb.go"))
	writeFile(t, repo, "api/x.pb.go", "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage api\nvar x = 1\n")
	gitRun(t, repo, "add", "-A")
	gitRun(t, repo, "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "regenerated")
	after := strings.TrimSpace(gitRun(t, repo, "rev-parse", "HEAD:api/x.pb.go"))

	conn := mustDB(t)
	registerFixture(t, conn)
	issue := createIssue(t, conn, "regenerated deep", "body", "task", nil)
	run := startRun(t, conn, issue)
	_, err := activate(conn, run.ID)
	testsupport.Must(t, err, "activate: %v", err)
	execSQL(t, conn, `UPDATE runs SET exec_root = ? WHERE id = ?`, repo, run.ID)

	var b strings.Builder
	fmt.Fprintf(&b, "diff --git a/api/x.pb.go b/api/x.pb.go\nindex %s..%s 100644\n--- a/api/x.pb.go\n+++ b/api/x.pb.go\n@@ -4000,3 +4000,3 @@\n", blob, after)
	for b.Len() < 800*1024 {
		b.WriteString("+var _ = \"regenerated filler line that is long enough to add up quickly\"\n")
	}
	diff := b.String() + handWritten
	e := testEngine()
	e.HeadFn = nil // the worktree is a plain directory: no head to record or bind
	e.DiffFn = func(_, _ string, _ []string) (string, error) { return diff, nil }
	completeStepAt(t, conn, e, issue, "implement@0", t.TempDir())

	rendered, err := RenderStep(conn, stepIDIn(t, conn, issue, "review@0#0"), "", nowMS)
	testsupport.Must(t, err, "RenderStep: %v", err)
	if len(rendered.Packet) >= packetCap {
		t.Errorf("rendered packet is %d bytes; want under %d", len(rendered.Packet), packetCap)
	}
	if !strings.Contains(rendered.Packet, handWritten) {
		t.Error("the hand-written hunks are not intact")
	}
}
